[CmdletBinding()]
param(
  [string]$DataRoot = '',
  [switch]$Embedded,
  [string]$BootstrapFile = '',
  # Session token generated by the WPF client; never written to disk by the server.
  [string]$Token = '',
  # Create or verify the data root as an administrators-only directory.
  [switch]$SecureDataRoot
)
# Garant-PO v6.0: isolated local-only multi-threaded .NET host (Windows PowerShell 5.1).
$ErrorActionPreference='Stop'
# When this Windows PowerShell 5.1 host is started from PowerShell 7, it inherits
# PowerShell 7 module paths and then fails to load built-in modules such as
# Microsoft.PowerShell.Security (Get-Acl, Get-AuthenticodeSignature). Workers
# inherit this environment, so keep only Windows PowerShell module locations.
$env:PSModulePath = (@($env:PSModulePath -split ';') | Where-Object { $_ -and ($_ -notmatch '\\PowerShell\\' -or $_ -match '\\WindowsPowerShell\\') }) -join ';'
$root=$PSScriptRoot
$dataRoot=if ([string]::IsNullOrWhiteSpace($DataRoot)) { $root } else { [System.IO.Path]::GetFullPath($DataRoot) }
if ($SecureDataRoot) {
  . (Join-Path $root 'SecureRoot.ps1')
  try { $dataRoot = Initialize-GSSecureDataRoot -Path $dataRoot }
  catch {
    if ($BootstrapFile) {
      $failure = [ordered]@{ ok=$false; error=$_.Exception.Message }
      [IO.File]::WriteAllText($BootstrapFile,(ConvertTo-Json -InputObject $failure -Compress),[Text.UTF8Encoding]::new($false))
    }
    throw
  }
}
New-Item -ItemType Directory -Force -Path $dataRoot | Out-Null
$env:GARANT_PO_DATA_ROOT=$dataRoot
if([string]::IsNullOrWhiteSpace($env:GARANT_PO_DOWNLOAD_DIR) -or [string]::IsNullOrWhiteSpace($env:GARANT_PO_DRIVER_DIR) -or [string]::IsNullOrWhiteSpace($env:GARANT_PO_LIBRARY_DIR)){
  $userDownloads=''
  try {
    $shell=New-Object -ComObject Shell.Application
    try {$downloadsFolder=$shell.Namespace('shell:Downloads');if($downloadsFolder -and $downloadsFolder.Self.Path){$userDownloads=[string]$downloadsFolder.Self.Path}}
    finally {if($shell){[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($shell)}}
  } catch {}
  if([string]::IsNullOrWhiteSpace($userDownloads)){
    $profile=[Environment]::GetFolderPath([Environment+SpecialFolder]::UserProfile)
    if([string]::IsNullOrWhiteSpace($profile)){$profile=$env:USERPROFILE}
    $userDownloads=Join-Path $profile 'Downloads'
  }
  $publicRoot=Join-Path $userDownloads 'Garant Store'
  if([string]::IsNullOrWhiteSpace($env:GARANT_PO_DOWNLOAD_DIR)){$env:GARANT_PO_DOWNLOAD_DIR=Join-Path $publicRoot 'Drivers'}
  if([string]::IsNullOrWhiteSpace($env:GARANT_PO_DRIVER_DIR)){$env:GARANT_PO_DRIVER_DIR=Join-Path $publicRoot 'Drivers'}
  if([string]::IsNullOrWhiteSpace($env:GARANT_PO_LIBRARY_DIR)){$env:GARANT_PO_LIBRARY_DIR=Join-Path $publicRoot 'Libraries'}
}
New-Item -ItemType Directory -Force -Path (Join-Path $dataRoot 'Logs') | Out-Null
try {
  Add-Type -Path (Join-Path $root 'GarantServer.cs') -ReferencedAssemblies @('System.dll','System.Core.dll','System.Web.Extensions.dll','System.IO.Compression.dll','System.IO.Compression.FileSystem.dll') -ErrorAction Stop
  $hostApp=New-Object -TypeName GarantPO.Host -ArgumentList @($root,$dataRoot,[bool]$Embedded,$BootstrapFile,$Token)
  $hostApp.Run()
} catch {
  $details=$_.Exception.ToString()+' '+($_ | Out-String)
  Add-Content -Path (Join-Path $dataRoot 'Logs\Garant-PO-Server-Startup-Error.log') -Value $details -Encoding UTF8
  Write-Host $details -ForegroundColor Red
  throw
}
